// OpenAI Go SDK Strict JSON Schema
package main

import (
	"context"
	"fmt"
	"github.com/openai/openai-go"
)

type CalendarEvent struct {
	Title        string   `json:"title"`
	Date         string   `json:"date"`
	Participants []string `json:"participants"`
}

func main() {
	client := openai.NewClient()
	schema := openai.GenerateSchema[CalendarEvent]()

	chat, _ := client.Chat.Completions.New(context.Background(), openai.ChatCompletionNewParams{
		Model: openai.F(openai.ChatModelGPT4o),
		Messages: openai.F([]openai.ChatCompletionMessageParamUnion{
			openai.UserMessage("Dinner with Alice tomorrow at 7pm"),
		}),
		ResponseFormat: openai.F[openai.ChatCompletionNewParamsResponseFormatUnion](
			openai.ResponseFormatJSONSchemaParam{
				Type: openai.F(openai.ResponseFormatJSONSchemaTypeJSONSchema),
				JSONSchema: openai.F(openai.ResponseFormatJSONSchemaJSONSchemaParam{
					Name:   openai.F("calendar_event"),
					Schema: openai.F(schema),
					Strict: openai.Bool(true),
				}),
			},
		),
	})
	fmt.Println(chat.Choices[0].Message.Content)
}

