// Anthropic Go Prompt Caching with Ephemeral Control
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
)

func main() {
	body, _ := json.Marshal(map[string]interface{}{
		"model":      "claude-3-5-sonnet-20241022",
		"max_tokens": 1024,
		"system": []map[string]interface{}{
			{
				"type": "text",
				"text": "You are a specialized legal analysis assistant...",
				"cache_control": map[string]string{"type": "ephemeral"}, // 90% read discount
			},
		},
		"messages": []map[string]string{
			{"role": "user", "content": "Analyze clause 4b in the cached contract."},
		},
	})

	req, _ := http.NewRequest("POST", "https://api.anthropic.com/v1/messages", bytes.NewBuffer(body))
	req.Header.Set("x-api-key", os.Getenv("ANTHROPIC_API_KEY"))
	req.Header.Set("anthropic-version", "2023-06-01")
	req.Header.Set("anthropic-beta", "prompt-caching-2024-07-31")
	req.Header.Set("content-type", "application/json")

	resp, _ := http.DefaultClient.Do(req)
	defer resp.Body.Close()
	fmt.Println("Status:", resp.Status)
}

