// Gemini 2.0 Flash Audio Ingestion in Go
package main

import (
	"context"
	"fmt"
	"os"
	"github.com/google/generative-ai-go/genai"
	"google.golang.org/api/option"
)

func main() {
	ctx := context.Background()
	client, _ := genai.NewClient(ctx, option.WithAPIKey(os.Getenv("GEMINI_API_KEY")))
	defer client.Close()

	model := client.GenerativeModel("gemini-2.0-flash")
	audioData, _ := os.ReadFile("meeting_recording.mp3")

	resp, _ := model.GenerateContent(ctx,
		genai.Blob{MIMEType: "audio/mp3", Data: audioData},
		genai.Text("Transcribe this conversation and summarize action items with speaker timestamps."),
	)

	for _, cand := range resp.Candidates {
		for _, part := range cand.Content.Parts {
			fmt.Println(part)
		}
	}
}

